   "DELETE v FROM visits v JOIN patients p ON p.id=v.patient_id WHERE $like","DELETE FROM patients WHERE patient_no LIKE 'TST%'","DELETE FROM messages WHERE from_id IN ($ue) OR to_id IN ($ue)","DELETE FROM login_otps WHERE user_id IN ($ue)","DELETE FROM password_resets WHERE user_id IN ($ue)","DELETE FROM users WHERE email LIKE '%@test.local'"] as $sql){try{$pdo->exec($sql);}catch(Exception $x){}}
