    foreach(['Malaria RDT'=>200,'Full Haemogram'=>500,'Blood Sugar'=>150,'Urinalysis'=>150,'Stool Microscopy'=>200,'Haemoglobin'=>150,'Pregnancy Test'=>100,'Widal Test'=>300] as $n=>$pr)$ex('INSERT IGNORE INTO lab_tests(name,price) VALUES(?,?)',[$n,$pr]);
