    $T=[];foreach($pdo->query('SELECT id,name,price FROM lab_tests') as $r)$T[$r['name']]=[$r['id'],$r['price']];$D=[];foreach($pdo->query('SELECT id,name,price FROM drugs') as $r)$D[$r['name']]=[$r['id'],$r['price']];
