    $pt=[['Mary','Wanjiku','Female',34],['John','Kamau','Male',45],['Grace','Njeri','Female',28],['Peter','Mwangi','Male',52],['Faith','Wambui','Female',24],['Joseph','Kariuki','Male',61],['Esther','Muthoni','Female',31],['Samuel','Gitau','Male',38],['Lucy','Wangari','Female',29],['David','Maina','Male',19],['Ian','Kamau','Male',2],['Brenda','Njoki','Female',4],['Kevin','Mwaura','Male',9],['Ann','Nyambura','Female',67]];$pids=[];
    foreach($pt as $i=>$p){$ex('INSERT INTO patients(patient_no,first_name,last_name,gender,dob,id_number,phone,address,next_of_kin,nok_phone) VALUES(?,?,?,?,?,?,?,?,?,?)',['TST'.sprintf('%03d',$i+1),$p[0],$p[1],$p[2],date('Y-m-d',strtotime("-{$p[3]} years -".mt_rand(5,300).' days')),'3000'.sprintf('%04d',$i+1),'07000000'.sprintf('%02d',$i+1),"Murang'a",'Test Relative','0700000099']);$pids[]=(int)$pdo->lastInsertId();}
    $dept=[];foreach(depts() as $d)$dept[$d['slug']]=$d['id'];$rnd=function($a){return $a[mt_rand(0,count($a)-1)];};$bank=0;$fee=CONSULT_FEE;
