        $st=$day?'done':['registered','consultation','consultation','lab','pharmacy','done','done','done'][$j];if($st=='lab'&&!$c[4])$st='consultation';if($st=='pharmacy'&&!$c[5])$st='consultation';
        $ex('INSERT INTO visits(patient_id,dept_id,reason,status,created_at) VALUES(?,?,?,?,?)',[$pid,$dept[$c[1]],$c[0],$st,$f($ts)]);$vid=(int)$pdo->lastInsertId();$items=$fee>0?[['Consultation fee',$fee,'fee',$vid]]:[];
