        if(in_array($st,['lab','pharmacy','done'])){$ex('INSERT INTO consultations(visit_id,history,examination,diagnosis,icd10,plan,outcome,doctor_id,created_at) VALUES(?,?,?,?,?,?,?,?,?)',[$vid,$c[0].' for a few days','Examined, no distress',$c[2],$c[3],'Treat as prescribed and review if no improvement',$st=='lab'?'lab':'pharmacy',$uid['doctor'],$f($ts+1800)]);
          foreach($c[4] as $tn){$dn=$st!='lab';$ex('INSERT INTO lab_orders(visit_id,test_id,status,result,abnormal,ordered_by,done_by,created_at,done_at) VALUES(?,?,?,?,?,?,?,?,?)',[$vid,$T[$tn][0],$dn?'done':'pending',$dn?$rnd(['Normal','Positive','Negative','Within range']):null,$dn&&mt_rand(0,3)==0?1:0,$uid['doctor'],$dn?$uid['lab']:null,$f($ts+2000),$dn?$f($ts+3600):null]);if($st=='done')$items[]=['Lab: '.$tn,$T[$tn][1],'lab',(int)$pdo->lastInsertId()];}
          if($st!='lab')foreach($c[5] as $dn){$qty=mt_rand(6,20);$ds=$st=='done';$ex('INSERT INTO prescriptions(visit_id,drug_id,dose,duration,qty,status,prescribed_by,dispensed_by,created_at) VALUES(?,?,?,?,?,?,?,?,?)',[$vid,$D[$dn][0],'1 dose, 3 times a day','5 days',$qty,$ds?'dispensed':'pending',$uid['doctor'],$ds?$uid['pharmacist']:null,$f($ts+2200)]);if($ds)$items[]=["Drug: $dn x$qty",$qty*$D[$dn][1],'rx',(int)$pdo->lastInsertId()];}
          if($st=='done'&&mt_rand(0,2)==0)$ex('INSERT INTO patient_notes(patient_id,visit_id,dept_id,author_id,title,body,created_at) VALUES(?,?,?,?,?,?,?)',[$pid,$vid,$dept[$c[1]],$uid['doctor'],'Progress note','<p><b>Review:</b> patient improving, advised to return if symptoms worsen.</p>',$f($ts+2400)]);}
        $tot=array_sum(array_column($items,1));$paid=$st=='registered'?0:($st=='done'?$tot:$fee);$is=$paid<=0?'unpaid':($paid>=$tot?'paid':'partial');
        if($items){$ex('INSERT INTO invoices(patient_id,visit_id,total,paid,status,created_by,created_at) VALUES(?,?,?,?,?,?,?)',[$pid,$vid,$tot,$paid,$is,$uid['cashier'],$f($ts+60)]);$iid=(int)$pdo->lastInsertId();
          foreach($items as $it)$ex('INSERT INTO invoice_items(invoice_id,description,amount,source,ref_id) VALUES(?,?,?,?,?)',[$iid,$it[0],$it[1],$it[2],$it[3]]);
          if($paid>0){$pay($iid,min($fee,$paid),$ts+300);if($paid>$fee)$pay($iid,$paid-$fee,$ts+4000);}}}}
    foreach([[3,0,'Severe malaria'],[5,1,'Pneumonia']] as $a){$ex('INSERT INTO visits(patient_id,dept_id,reason,status,created_at) VALUES(?,?,?,?,?)',[$pids[$a[0]],$dept['general-opd'],$a[2],'admitted',$f(time()-86400)]);$vid=(int)$pdo->lastInsertId();$ex('INSERT INTO admissions(patient_id,visit_id,bed_id,reason,admitted_at,admitted_by) VALUES(?,?,?,?,?,?)',[$pids[$a[0]],$vid,$bed[$a[1]],$a[2],$f(time()-86400),$uid['doctor']]);}
    foreach([[0,'Review',1],[2,'ANC visit',2],[7,'Blood pressure check',3]] as $b)$ex('INSERT INTO bookings(patient_id,dept_id,service,booked_for,created_by) VALUES(?,?,?,?,?)',[$pids[$b[0]],$dept['general-opd'],$b[1],date('Y-m-d 09:00:00',strtotime('+'.$b[2].' day')),$uid['receptionist']]);
