    $pdo->commit();
    try{foreach([[4,'TST-B1','Male',32,1800,'Prematurity','C1','Oxygen','NG tube',1,'-6 hours'],[6,'TST-B2','Female',39,3200,'Neonatal jaundice','C4','None','Breastfeeding',1,'-3 days']] as $k=>$b){
      $mo=$pt[$b[0]];$ex('INSERT INTO patients(patient_no,first_name,last_name,gender,dob,phone,next_of_kin) VALUES(?,?,?,?,?,?,?)',[$b[1],'Baby of '.$mo[0],$mo[1],$b[2],date('Y-m-d',strtotime($b[10])),'07000000'.sprintf('%02d',$b[0]+1),$mo[0].' '.$mo[1].' (mother)']);$bid=(int)$pdo->lastInsertId();
      $ex("INSERT INTO visits(patient_id,dept_id,reason,status) VALUES(?,?,?,'admitted')",[$bid,$dept['nbu'],'NBU admission: '.$b[5]]);$vid=(int)$pdo->lastInsertId();$bt=date('Y-m-d H:i:s',strtotime($b[10]));
      $ex('INSERT INTO nbu_admissions(baby_patient_id,mother_patient_id,visit_id,birth_at,sex,gestation_weeks,birth_weight_g,apgar1,apgar5,apgar10,delivery_mode,place_of_birth,reason,cot_no,resp_support,feeding,phototherapy,kmc,vit_k,bcg,opv0,hepb,eye_prophylaxis,maternal_notes,created_by,admitted_at) VALUES(?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,1,1,1,1,1,?,?,?)',[$bid,$pids[$b[0]],$vid,$bt,$b[2],$b[3],$b[4],6,8,9,'SVD','This hospital',$b[5],$b[6],$b[7],$b[8],$k?1:0,$k?0:1,'Attended 3 antenatal visits. No known infections.',$uid['nurse'],$bt]);$aid=(int)$pdo->lastInsertId();
      for($e=0;$e<4;$e++)$ex('INSERT INTO nbu_charts(adm_id,recorded_at,temp,hr,rr,spo2,weight_g,feed_type,feed_ml,notes,nurse_id) VALUES(?,?,?,?,?,?,?,?,?,?,?)',[$aid,date('Y-m-d H:i:s',time()-(3-$e)*3600*($k?8:1)),$e==1&&!$k?36.1:36.8,mt_rand(125,160),mt_rand(40,62),mt_rand(89,97),$b[4]-mt_rand(0,40)+$e*5,$b[8]=='NG tube'?'NG tube':'Breast',mt_rand(10,30),'Routine check',$uid['nurse']]);}}catch(Exception $x){}
    try{$vs=$pdo->query("SELECT v.id,v.patient_id FROM visits v JOIN patients p ON p.id=v.patient_id WHERE p.patient_no LIKE 'TST%' AND v.status='done' ORDER BY v.id LIMIT 8")->fetchAll();$ie=$pdo->query('SELECT id FROM imaging_exams ORDER BY id')->fetchAll(PDO::FETCH_COLUMN);$pc=$pdo->query('SELECT id FROM procedures_catalog ORDER BY id')->fetchAll(PDO::FETCH_COLUMN);
      foreach($vs as $i=>$v){if($i<5)$ex("INSERT INTO imaging_orders(visit_id,exam_id,clinical_info,status,findings,impression,ordered_by,performed_by,reported_at) VALUES(?,?,?,'reported',?,?,?,?,NOW())",[$v['id'],$ie[$i%count($ie)],'Test clinical information','No acute abnormality seen.','Normal study.',$uid['doctor'],$uid['radiographer']]);
        if($i%2==0)$ex("INSERT INTO procedure_orders(visit_id,proc_id,indication,status,outcome,consent,ordered_by,performed_by,done_at) VALUES(?,?,?,'done',?,1,?,?,NOW())",[$v['id'],$pc[$i%count($pc)],'Test indication','Procedure done without problems.',$uid['doctor'],$uid['nurse']]);}
