      foreach([[10,99],[11,2]] as $cc){$dob=$pdo->query('SELECT dob FROM patients WHERE id='.(int)$pids[$cc[0]])->fetchColumn();foreach($SC as $k=>$s)if($k<$cc[1]&&strtotime($dob.' +'.($s[2]*7).' days')<time())$ex("INSERT IGNORE INTO immunization_records(patient_id,kind,item,dose_no,given_at,batch_no,given_by) VALUES(?,?,?,?,?,?,?)",[$pids[$cc[0]],'vaccine',$s[0],$s[1],date('Y-m-d',strtotime($dob.' +'.($s[2]*7).' days')),'TSTV'.sprintf('%03d',$k),$uid['nurse']]);}
      $ex("INSERT INTO immunization_records(patient_id,kind,item,given_at,batch_no,next_due,given_by) VALUES(?,?,?,?,?,?,?)",[$pids[10],'vitamin_a','Vitamin A',date('Y-m-d',strtotime('-1 month')),'TSTA01',date('Y-m-d',strtotime('+5 months')),$uid['nurse']]);
      $ex("INSERT INTO nutrition_assessments(patient_id,weight_kg,height_cm,muac_mm,classification,advice,assessed_by) VALUES(?,?,?,?,?,?,?),(?,?,?,?,?,?,?)",[$pids[10],12.5,88,138,'Normal','Continue breastfeeding and a balanced diet. Review at the next visit.',$uid['nurse'],$pids[11],11.2,98,112,'SAM (severe acute malnutrition)','Refer for stabilization and therapeutic feeding (RUTF). Review weekly.',$uid['nurse']]);
    }catch(Exception $x){}
    $cred=true;$msg='Test data added.';}catch(Exception $x){if($pdo->inTransaction())$pdo->rollBack();$msg='Could not add test data: '.$x->getMessage().' (have you imported stage11.sql?)';}}
