if($cred)echo '<div class=card><b>Test staff accounts</b> (password for all: <code>Test@1234</code>)<br>receptionist@test.local, nurse@test.local, doctor@test.local, lab@test.local, pharmacist@test.local, cashier@test.local, records@test.local, radiographer@test.local<p>Login codes for these accounts are written to <code>otp.log</code> in the project folder.</p></div>';?>
